<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/bootstrap.php';
use FudgeDonuts\{Database,FoodComplianceService};
require_admin_roles(['super_admin','admin']);
$db=Database::connection();$svc=new FoodComplianceService($db);$error='';$notice='';
$id=(int)($_GET['id']??$_POST['flavor_id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf($_POST['_csrf']??null);
 try{$svc->save($id,$_POST,(int)$_SESSION['admin_id']);$notice='Compliance profile saved.';}catch(Throwable $e){$error=$e->getMessage();}
}
$rows=$svc->all();$summary=$svc->summary();$current=$id?$svc->profile($id):null;
