<section class="dashboard-kpis"><article class="kpi-card"><span>Active flavors</span><strong><?=$summary['active']?></strong></article><article class="kpi-card"><span>Complete</span><strong><?=$summary['complete']?></strong></article><article class="kpi-card"><span>Published</span><strong><?=$summary['published']?></strong></article><article class="kpi-card <?=$summary['incomplete']?'kpi-alert':''?>"><span>Incomplete</span><strong><?=$summary['incomplete']?></strong></article></section>
