<?php if($current):?><div class="dashboard-panel"><h2><?=htmlspecialchars($current['name'])?></h2><form method="post" class="admin-form"><input type="hidden" name="_csrf" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="flavor_id" value="<?=$id?>"><label>Ingredient statement<textarea name="ingredient_statement" rows="5" required><?=htmlspecialchars($current['ingredient_statement'])?></textarea></label><label>Allergen statement<textarea name="allergen_statement" rows="3" required><?=htmlspecialchars($current['allergen_statement'])?></textarea></label><label>Shared-kitchen notice<textarea name="shared_kitchen_notice" rows="3"><?=htmlspecialchars($current['shared_kitchen_notice'])?></textarea></label><label>Storage instructions<textarea name="storage_instructions" rows="3" required><?=htmlspecialchars($current['storage_instructions'])?></textarea></label><div class="two"><label>Shelf life (days)<input type="number" min="1" max="365" name="shelf_life_days" required value="<?=htmlspecialchars((string)$current['shelf_life_days'])?>"></label><label>Net weight (oz)<input type="number" min=".01" step=".01" name="net_weight_oz" required value="<?=htmlspecialchars((string)$current['net_weight_oz'])?>"></label></div><label>Label version<input name="label_version" required value="<?=htmlspecialchars($current['label_version'])?>"></label><label class="check"><input type="checkbox" name="published" value="1" <?=(int)$current['published']?'checked':''?>> Publish to customers</label><button class="button">Save compliance profile</button></form></div><?php else:?><div class="dashboard-panel"><div class="dashboard-empty">Choose a flavor to edit its compliance profile.</div></div><?php endif;?></section></main></body></html>